  <script>
    function descargarArchivo(nombreArchivo, contenidoBase64) {
        // Decodificar el contenido base64
        const contenido = atob(contenidoBase64);

        // Crear un Blob a partir del contenido decodificado
        const blob = new Blob([contenido], { type: 'text/xml' });

        // Crear una URL para el Blob
        const blobUrl = URL.createObjectURL(blob);

        // Crear un enlace de descarga
        const a = document.createElement('a');
        a.href = blobUrl;
        a.download = nombreArchivo;

        // Simular clic en el enlace para iniciar la descarga
        a.click();

        // Liberar recursos
        URL.revokeObjectURL(blobUrl);
    }

    function ver_xml() {
        const xmlBase64 = ""; // Aquí debes poner el base64 de tu XML
        const nombreArchivo = 'archivo.xml';

        descargarArchivo(nombreArchivo, xmlBase64);
    }

    function ver_factura() {
      var byteCharacters = atob("");
      var byteNumbers = new Array(byteCharacters.length);
      for (var i = 0; i < byteCharacters.length; i++) {
          byteNumbers[i] = byteCharacters.charCodeAt(i);
      }
      var byteArray = new Uint8Array(byteNumbers);
      var blob = new Blob([byteArray], { type: 'application/pdf' });

      // Crear una URL para el Blob
      var blobUrl = URL.createObjectURL(blob);

      // Abrir una nueva pestaña con el PDF
      var newTab = window.open();
      newTab.document.write('<iframe src="' + blobUrl + '" width="100%" height="100%"></iframe>');
    }
    function showAlert() {
      var alert = document.getElementById('alert');
      alert.style.display = 'block';
    }
    function closeAlert() {
      var alert = document.querySelector('.alert');
      alert.style.display = 'none';
      document.querySelector(".ver-factura-btn").classList.remove("d-none");
      $(".ver-factura-btn").css("display", "block");
    }
    function facturar(){
      var data = $('#data').val();
      $.ajax({
          url: "facturacion/facturacion.php", // Ruta de tu archivo PHP
          method: "GET", // Cambiado a GET
          data: { data: data }, // Enviar el valor en la solicitud
          success: function(data) {
            var lines = data.split('\n');
            var thirdLine = lines[2];
            alert(data); // Mostrar la respuesta en una alerta
          },
          error: function() {
              alert("Error al llamar a la función de PHP");
          }
      });
    }
    //Validar si mostrar o no boton de factura
    var esFactura = $("#esFactura").val();
    
    if (esFactura === "false") {
      $(".facturar-btn").css("display", "none");
    }else{
      $(".ver-factura-btn").css("display", "none");
    }    



</script>